def classify_existing_invoices(apps, schema_editor):
    """Attribue le bon type aux factures existantes avant le passage en ForeignKey.

    Les documents d'annulation sont identifiables par leur ligne CORRECTION
    "Annulation - Montant conservé" ; toutes les autres factures existantes
    sont des factures de location.
    """
    Invoice = apps.get_model("invoicing", "Invoice")
    cancellation_ids = Invoice.objects.filter(
        lines__line_type="CORRECTION",
        lines__description="Annulation - Montant conservé",
    ).values_list("id", flat=True)
    Invoice.objects.filter(id__in=list(cancellation_ids)).update(invoice_type="ANNULATION")


